tape( 'the returned constructor returns an array (iterable) (complex128)', function test( t ) {
	var Complex128Array;
	var arr;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( createIterable() );
	t.strictEqual( arr instanceof Complex128Array, true, 'returns expected value' );
	t.end();

	function createIterable() {
		var it = {};
		it[ ITERATOR_SYMBOL ] = iterable;
		return it;

		function iterable() {
			return {
				'next': next
			};
		}

		function next() {
			return {
				'done': true
			};
		}
	}
});

