tape( 'the returned constructor instance has a `length` property (iterable) (complex128)', function test( t ) {
	var Complex128Array;
	var iter1;
	var iter2;
	var arr;
	var v;

	Complex128Array = factory( 'complex128' );

	iter1 = {
		'next': next1,
		'i': 0,
		'N': 4
	};
	arr = new Complex128Array( createIterable( iter1 ) );
	v = arr.length;
	t.strictEqual( v, iter1.N, 'returns expected value' );

	iter2 = {
		'next': next2,
		'i': 0,
		'N': 4
	};
	arr = new Complex128Array( createIterable( iter2 ) );
	v = arr.length;
	t.strictEqual( v, iter2.N, 'returns expected value' );

	t.end();

	function createIterable( iterator ) {
		var it = {};
		it[ ITERATOR_SYMBOL ] = iterable;
		return it;

		function iterable() {
			return iterator;
		}
	}

	function next1() {
		iter1.i += 1;
		if ( iter1.i <= iter1.N ) {
			return {
				'value': [ 1.0, 1.0 ]
			};
		}
		return {
			'done': true
		};
	}

	function next2() {
		iter2.i += 1;
		if ( iter2.i <= iter2.N ) {
			return {
				'value': new Complex128( 1.0, 1.0 )
			};
		}
		return {
			'done': true
		};
	}
});

