tape( 'the returned constructor throws an error if provided an ArrayBuffer whose byte length is not a multiple of BYTES_PER_ELEMENT (complex128)', function test( t ) {
	var Complex128Array;
	var values;
	var i;

	Complex128Array = factory( 'complex128' );

	values = [ 1, 2, 3, 4, 5, 6, 7, 9, 24, 74, 801 ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), RangeError, 'throws an error when provided an ArrayBuffer having a byte length equal to '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return new Complex128Array( new ArrayBuffer( value ) );
		};
	}
});

